import { useEffect, useState } from 'react';

// World locations for the address pickers: countries, first-level subdivisions (province / state / …) and
// their cities. The data lives in public/geo/*.json, generated by scripts/build-geo.mjs from
// dr5hn/countries-states-cities-database (ODbL, see public/geo/ATTRIBUTION.md) plus the official Indonesian
// list (38 provinces, 514 kabupaten/kota). Only countries.json and the selected country's file are
// fetched, on demand, and kept in memory; the service worker caches them for offline use.
//
// The getters are synchronous and return what is loaded so far; components call useWorldLocations() so
// they re-render when a file arrives.

export interface CountryOption {
  name: string;
  isoCode: string;
  flag: string;
}

export interface ProvinceOption {
  name: string;
  isoCode: string;
}

interface GeoCountryIndexEntry {
  iso2: string;
  name: string;
  emoji?: string;
}

interface GeoState {
  name: string;
  code: string;
  type?: string;
  cities: string[];
  aliases?: string[];
}

interface GeoCountry {
  iso2: string;
  name: string;
  subdivisionLabel?: string;
  states: GeoState[];
}

const GEO_BASE = '/geo';

// Rendered until countries.json arrives, so the default selection (Indonesia) shows immediately
const INDONESIA: CountryOption = { name: 'Indonesia', isoCode: 'ID', flag: '🇮🇩' };

let countriesCache: CountryOption[] | null = null;
let countriesPromise: Promise<CountryOption[]> | null = null;
const countryCache = new Map<string, GeoCountry>();
const countryPromises = new Map<string, Promise<GeoCountry | null>>();
const listeners = new Set<() => void>();

const notify = () => listeners.forEach((listener) => listener());
const norm = (value: string | undefined | null) => (value || '').trim().toLowerCase();

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
  return (await res.json()) as T;
}

/**
 * Loads the list of all 250 countries / territories (Indonesia first, then alphabetical).
 */
export function loadCountries(): Promise<CountryOption[]> {
  if (countriesCache) return Promise.resolve(countriesCache);
  if (!countriesPromise) {
    countriesPromise = fetchJson<GeoCountryIndexEntry[]>(`${GEO_BASE}/countries.json`)
      .then((list) => {
        const mapped = list.map((c) => ({ name: c.name, isoCode: c.iso2, flag: c.emoji || '🌐' }));
        const indonesia = mapped.find((c) => c.isoCode === 'ID');
        const others = mapped.filter((c) => c.isoCode !== 'ID').sort((a, b) => a.name.localeCompare(b.name));
        countriesCache = indonesia ? [indonesia, ...others] : others;
        notify();
        return countriesCache;
      })
      .catch((err) => {
        countriesPromise = null; // allow a retry on the next render
        console.warn('Could not load the country list:', err);
        throw err;
      });
  }
  return countriesPromise;
}

export function getAllCountriesList(): CountryOption[] {
  return countriesCache ?? [INDONESIA];
}

export function findCountryByNameOrCode(countryNameOrCode: string): CountryOption | undefined {
  if (!countryNameOrCode) return undefined;
  const list = getAllCountriesList();
  const normalized = norm(countryNameOrCode);
  return (
    list.find((c) => norm(c.name) === normalized || norm(c.isoCode) === normalized) ||
    list.find((c) => norm(c.name).includes(normalized))
  );
}

/**
 * Loads one country's subdivisions and cities (cached). Resolves null when the file cannot be loaded.
 */
export function loadCountry(countryNameOrCode: string): Promise<GeoCountry | null> {
  const country = findCountryByNameOrCode(countryNameOrCode);
  if (!country) return Promise.resolve(null);
  const iso = country.isoCode;
  const cached = countryCache.get(iso);
  if (cached) return Promise.resolve(cached);
  let pending = countryPromises.get(iso);
  if (!pending) {
    pending = fetchJson<GeoCountry>(`${GEO_BASE}/${iso}.json`)
      .then((data) => {
        countryCache.set(iso, data);
        notify();
        return data;
      })
      .catch((err) => {
        countryPromises.delete(iso);
        console.warn(`Could not load locations for ${iso}:`, err);
        return null;
      });
    countryPromises.set(iso, pending);
  }
  return pending;
}

function getLoadedCountry(countryNameOrCode: string): GeoCountry | undefined {
  const country = findCountryByNameOrCode(countryNameOrCode);
  return country ? countryCache.get(country.isoCode) : undefined;
}

/**
 * True once the country's subdivisions / cities are loaded (the getters below return real data).
 */
export function isCountryLoaded(countryNameOrCode: string): boolean {
  return !!getLoadedCountry(countryNameOrCode);
}

function findState(data: GeoCountry, stateNameOrCode: string): GeoState | undefined {
  const normalized = norm(stateNameOrCode);
  if (!normalized) return undefined;
  return data.states.find(
    (s) =>
      norm(s.name) === normalized ||
      norm(s.code) === normalized ||
      (s.aliases || []).some((alias) => norm(alias) === normalized)
  );
}

/**
 * Canonical subdivision name for a stored value (e.g. a legacy "Jakarta" -> "DKI Jakarta"), or null
 * when it is not in the loaded list.
 */
export function resolveStateName(countryNameOrCode: string, stateNameOrCode: string): string | null {
  const data = getLoadedCountry(countryNameOrCode);
  if (!data) return null;
  return findState(data, stateNameOrCode)?.name ?? null;
}

/**
 * Every first-level subdivision (province / state / region / prefecture …) of the country.
 * Empty while the country's file is still loading.
 */
export function getStatesOfCountryByName(countryNameOrCode: string): ProvinceOption[] {
  const country = findCountryByNameOrCode(countryNameOrCode);
  if (!country) {
    return [{ name: 'All Regions / General', isoCode: 'ALL' }];
  }
  const data = countryCache.get(country.isoCode);
  if (!data) return [];
  if (data.states.length === 0) {
    return [{ name: `${country.name} (National / All Regions)`, isoCode: 'ALL' }];
  }
  return data.states.map((s) => ({ name: s.name, isoCode: s.code }));
}

/**
 * Every city / regency / municipality of the country's subdivision. Empty while loading; a single
 * "<name> City / Center" entry when the data lists no cities there.
 */
export function getCitiesOfStateByName(countryNameOrCode: string, stateNameOrCode: string): string[] {
  const country = findCountryByNameOrCode(countryNameOrCode);
  if (!country) return [];
  const data = countryCache.get(country.isoCode);
  if (!data) return [];
  const state = findState(data, stateNameOrCode);
  if (state && state.cities.length > 0) return state.cities;
  return [state ? `${state.name} City / Center` : `${country.name} City / Center`];
}

/**
 * Loads the country list and the given country's locations, and re-renders the component whenever
 * location data arrives. Returns a counter to use as a useMemo dependency.
 */
export function useWorldLocations(countryNameOrCode: string): number {
  const [version, setVersion] = useState(0);

  useEffect(() => {
    const listener = () => setVersion((v) => v + 1);
    listeners.add(listener);
    return () => {
      listeners.delete(listener);
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    loadCountries()
      .catch(() => undefined)
      .then(() => {
        if (!cancelled && countryNameOrCode) loadCountry(countryNameOrCode);
      });
    return () => {
      cancelled = true;
    };
  }, [countryNameOrCode]);

  return version;
}
